// 配置类型定义：应用配置的唯一权威类型
export interface AppConfig {
  name: string;
  /** 结构化超时字段（首选） */
  timeout: { seconds: number };
  /** 遗留的扁平超时字段；结构化 timeout 缺失时兜底 */
  timeoutSeconds?: number;
}

// 配置加载器：raw JSON → AppConfig
import type { AppConfig } from './config-types.js';

const DEFAULT_TIMEOUT_SECONDS = 30;

function isTimeoutObject(value: unknown): value is { seconds: number } {
  return (
    typeof value === 'object' &&
    value !== null &&
    !Array.isArray(value) &&
    'seconds' in value &&
    typeof value.seconds === 'number'
  );
}

export function parseConfig(raw: Record<string, unknown>): AppConfig {
  if (typeof raw.name !== 'string' || raw.name.length === 0) {
    throw new Error('name is required');
  }

  const rawTimeout = raw.timeout;
  const structuredSeconds = isTimeoutObject(rawTimeout) ? rawTimeout.seconds : undefined;
  const legacySeconds = typeof raw.timeoutSeconds === 'number' ? raw.timeoutSeconds : undefined;

  // 结构化 timeout 优先；缺失时回退到遗留扁平字段；再缺省用默认值
  const seconds = structuredSeconds ?? legacySeconds ?? DEFAULT_TIMEOUT_SECONDS;

  return {
    name: raw.name,
    timeout: { seconds },
    timeoutSeconds: seconds,
  };
}

// 应用入口：装配配置并启动服务
import { parseConfig } from './loader.js';
import { startServer } from './server.js';

export function bootstrap(raw: Record<string, unknown>) {
  const config = parseConfig(raw);
  return startServer({ name: config.name, timeout: config.timeout });
}

// 服务启动器：消费 timeout.seconds 作为请求超时
export interface ServerOptions {
  name: string;
  timeout: { seconds: number };
}

export function startServer(opts: ServerOptions): { name: string; timeout: { seconds: number } } {
  return { name: opts.name, timeout: opts.timeout };
}

import { describe, it, expect } from 'vitest';
import { parseConfig } from '../src/loader.js';
import { bootstrap } from '../src/main.js';

describe('parseConfig', () => {
  it('解析基础字段（结构化 timeout）', () => {
    const cfg = parseConfig({ name: 'svc', timeout: { seconds: 60 } });
    expect(cfg.name).toBe('svc');
    expect(cfg.timeout).toEqual({ seconds: 60 });
  });

  it('结构化 timeout 缺失时回退到遗留 timeoutSeconds', () => {
    const cfg = parseConfig({ name: 'svc', timeoutSeconds: 45 });
    expect(cfg.timeout.seconds).toBe(45);
    expect(cfg.timeoutSeconds).toBe(45);
  });

  it('结构化 timeout 优先于遗留字段', () => {
    const cfg = parseConfig({ name: 'svc', timeout: { seconds: 10 }, timeoutSeconds: 20 });
    expect(cfg.timeout.seconds).toBe(10);
  });

  it('缺省 timeout 用默认 30', () => {
    const cfg = parseConfig({ name: 'svc' });
    expect(cfg.timeout.seconds).toBe(30);
    expect(cfg.timeoutSeconds).toBe(30);
  });

  it('name 缺失抛错', () => {
    expect(() => parseConfig({})).toThrow('name');
  });
});

describe('bootstrap', () => {
  it('透传配置到服务（结构化 timeout）', () => {
    const s = bootstrap({ name: 'svc', timeout: { seconds: 5 } });
    expect(s.timeout.seconds).toBe(5);
    expect(s.name).toBe('svc');
  });

  it('透传配置到服务（遗留 timeoutSeconds 兜底）', () => {
    const s = bootstrap({ name: 'svc', timeoutSeconds: 7 });
    expect(s.timeout.seconds).toBe(7);
    expect(s.name).toBe('svc');
  });
});

